  ],
  "steps": [
    {
      "name": "START / CLAMP (M201)",
      "entry": "Pallet arrives in test position (ZS-2008 rising edge / LDP X23) while cell in auto mode (X2), no ST20 fault active (ANI M299), and station idle (ANI M200).",
      "exit": "Clamp confirmed closed (ZS-2002A / X20 made and ZS-2002B / X21 clear)."
    },
    {
      "name": "FILL (M202)",
      "entry": "Clamp confirmed closed from step M201.",
      "exit": "PT-2001 reaches fill threshold (14.50 kPa / D100 >= D122) transitioning to STABILISE, or fill timeout (T21 8.0 s) / fault condition aborting to VENT."
    },
    {
      "name": "STABILISE (M203)",
      "entry": "Fill pressure reached (PT-2001 >= 14.50 kPa / D100 >= D122).",
      "exit": "Stabilisation timer elapsed (T22 done)."
    },
    {
      "name": "TEST (M204)",
      "entry": "Stabilisation timer done (T22 done).",
      "exit": "Test window timer elapsed (T23 done, 10.0 s)."
    },
    {
      "name": "VENT (M205)",
      "entry": "Test window complete (T23 done) or abort from active fault (M299 while busy).",
      "exit": "Vent time elapsed (T200 done), pack pressure vented below 1.00 kPa (D100 < K100), and PT-2001 healthy (ANI M292)."
    },
    {
      "name": "UNCLAMP (M206)",
      "entry": "Vent conditions satisfied (T200 done, D100 < 1.00 kPa, ANI M292).",
      "exit": "Clamp confirmed open (ZS-2002B / X21 made and ZS-2002A / X20 clear)."
    },
    {
      "name": "DONE / RESULT (M207)",
      "entry": "Clamp confirmed open (X21 ON, X20 OFF).",
      "exit": "Pallet departs from test position (ANI X23), returning station to idle."
    }
  ],
  "interlocks": [
    {
      "cause": "Pallet sensor (ZS-2008 / X23) drops and returns while test is running (M200 is ON)",
      "effect": "Must not restart sequence (prevented by ANI M200 in R8)."
    },
    {
      "cause": "Clamp confirmed closed signal lost or clamp not confirmed closed (ZS-2002A / X20 lost or ZS-2002B / X21 made)",
      "effect": "Fill valve (XV-2003 / Y21) cannot open / closes immediately."
    },
    {
      "cause": "Any active fault / E-stop lost (M299 ON) while busy (M200 ON)",
      "effect": "Aborts cycle to VENT (M205), isolates fill (Y21 OFF), and sets FAIL (M211)."
    },
    {
      "cause": "Pack pressure not below 1.00 kPa or PT-2001 signal fault (M292 ON) during vent",
      "effect": "Clamp release inhibited; station holds in VENT step (M205) with vent valve held open."
    },
    {
      "cause": "Manual vent pushbutton (PB-2010 / X25) pressed in manual mode (ANI X2)",
      "effect": "Opens vent valve (XV-2004 / Y22)."
    },
    {
      "cause": "Station not at DONE step (M207 not active)",
      "effect": "PASS (RS-2006 / Y23) and FAIL (RS-2007 / Y24) result signals to line controller inhibited."
    }
  ],
  "alarms": [
    {
      "name": "Fill timeout",
      "condition": "Test pressure (14.50 kPa) not reached within 8.0 s (T21 done in FILL step M202)",
      "action": "Sets M290, lights fault beacon HL-2011 (Y25), aborts cycle to VENT (M205), and sets FAIL result (M211)."
    },
    {
      "name": "Over-pressure",
      "condition": "Pack pressure PT-2001 exceeds 20.00 kPa (D100 > D123 / K2000)",
      "action": "Latches M291, lights fault beacon HL-2011 (Y25), closes fill valve, holds vent valve (Y22) open, and aborts to VENT with FAIL result."
    },
    {
      "name": "PT-2001 signal fault",
      "condition": "PT-2001 reading below -5.00 kPa (D100 < K-500, wire break)",
      "action": "Drives M292, contributes to general fault M299 / beacon HL-2011 (Y25), inhibits cycle start, and holds clamp release / unclamp."
    },
    {
      "name": "Supply air low",
      "condition": "Supply air switch PS-2009 (X22) lost while station is busy (M200)",
      "action": "Latches M293, lights fault beacon HL-2011 (Y25), aborts cycle to VENT with FAIL result."
    }
  ],
  "conflicts": [
    {
      "item": "stabilise_time",
      "narrative_says": "3 s",
      "parameter_sheet_says": "5.0 s (T22, changed from 3.0 s by MOC-2021-044)",
      "program_says": "5.0 s (R13: OUT T22 K50 on 100 ms timer = 5.0 s)",
      "authoritative": "parameter_sheet"
    },
    {
      "item": "vent_time",
      "narrative_says": "0.5 s",
      "parameter_sheet_says": "0.5 s (T24)",
      "program_says": "5.0 s (R21: OUT T200 K50 on FX5 100 ms base = 5.0 s, migrated from FX3 10 ms timer base without adjusting instruction)",
      "authoritative": "parameter_sheet"
    }
  ]
}
